#version 300 es
precision highp float;

uniform vec3 iResolution;
uniform float iTime;

out vec4 fragColor;

#define PI 3.14159265359

float Hash(vec2 p) {
    p = fract(p * vec2(123.45, 987.65));
    p += dot(p, p + 45.67);
    return fract(p.x * p.y);
}

float Noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = Hash(i);
    float b = Hash(i + vec2(1.0, 0.0));
    float c = Hash(i + vec2(0.0, 1.0));
    float d = Hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        f += amp * Noise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return f;
}

vec3 getColor(float density, vec3 rayDir) {
    vec3 lightDir = normalize(vec3(0.6, 0.5, -0.6));
    float diff = max(0.0, dot(normalize(rayDir), lightDir));

    vec3 cloudColor = mix(vec3(0.8, 0.8, 0.8), vec3(1.0, 1.0, 1.0), density);

    return cloudColor * (0.6 + 0.4 * diff) + vec3(0.1, 0.1, 0.1) * density;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    float time = iTime * 0.1;

    vec3 cameraPos = vec3(sin(time * 0.5) * 50.0, 10.0 + sin(time * 0.3) * 5.0, -time * 20.0);
    vec3 targetPos = vec3(0.0, 10.0, -time * 20.0 - 50.0);

    vec3 forward = normalize(targetPos - cameraPos);
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = normalize(cross(right, forward));

    float fov = PI / 3.0;
    vec3 rayDir = normalize(forward + right * uv.x * tan(fov * 0.5) * (iResolution.x / iResolution.y) + up * uv.y * tan(fov * 0.5));

    vec3 finalColor = vec3(0.5, 0.7, 0.9);

    float totalDensity = 0.0;
    float totalAlpha = 0.0;

    vec3 sunDir = normalize(vec3(sin(time * 0.1), cos(time * 0.1), -1.0));
    float sunIntensity = 1.0;
    if (dot(sunDir, rayDir) > 0.999) {
        finalColor = vec3(1.0, 0.8, 0.6) * 2.0;
    }

    vec3 rayOrigin = cameraPos;
    float stepSize = 1.0;
    float maxDistance = 300.0;

    for (float t = 0.0; t < maxDistance; t += stepSize) {
        vec3 p = rayOrigin + rayDir * t;
        p.y -= 10.0; // Raise clouds
        p.xz *= 0.01; // Scale clouds

        float cloudFactor = fbm(p.xz * 0.5 + p.y * 0.1) * 0.8 + Noise(p.xz * 2.0 + p.y * 0.5) * 0.2;
        cloudFactor = pow(cloudFactor, 1.5);

        float heightFade = smoothstep(0.0, 1.0, (clamp(p.y, 0.0, 100.0) - 5.0) / 10.0);
        cloudFactor *= (1.0 - heightFade);

        float density = max(0.0, cloudFactor - 0.5) * 0.5;
        density = clamp(density, 0.0, 1.0);

        vec3 cloudColor = getColor(density, rayDir);

        float alpha = 1.0 - exp(-density * stepSize * 0.5);
        finalColor = mix(finalColor, cloudColor, alpha);
        totalAlpha += alpha;

        if (totalAlpha > 0.99) break; 
    }

    // Sun rendering
    vec3 skyColor = mix(vec3(0.3, 0.5, 0.8), vec3(0.8, 0.9, 1.0), 0.5 + 0.5 * sin(time * 0.1 + PI * 0.5));

    float sunDot = max(0.0, dot(rayDir, sunDir));
    skyColor += sunIntensity * vec3(1.0, 0.9, 0.7) * pow(sunDot, 20.0);

    finalColor = mix(skyColor, finalColor, clamp(totalAlpha, 0.0, 1.0));

    fragColor = vec4(finalColor, 1.0);
}

