#ifdef GL_ES
precision highp float;
#endif

vec3 hash33(vec3 p) {
    p = fract(p * vec3(443.897, 441.423, 437.197));
    p += dot(p, p.yzx + 19.19);
    return fract(vec3(p.x * p.y, p.y * p.z, p.z * p.x));
}

float noise(vec3 x) {
    vec3 i = floor(x);
    vec3 f = fract(x);

    f = f * f * (3.0 - 2.0 * f);

    vec3 a = hash33(i + vec3(0.0, 0.0, 0.0));
    vec3 b = hash33(i + vec3(1.0, 0.0, 0.0));
    vec3 c = hash33(i + vec3(0.0, 1.0, 0.0));
    vec3 d = hash33(i + vec3(1.0, 1.0, 0.0));
    vec3 e = hash33(i + vec3(0.0, 0.0, 1.0));
    vec3 g = hash33(i + vec3(1.0, 0.0, 1.0));
    vec3 h = hash33(i + vec3(0.0, 1.0, 1.0));
    vec3 j = hash33(i + vec3(1.0, 1.0, 1.0));

    return mix(mix(mix(dot(a, f - vec3(0.0, 0.0, 0.0)), dot(b, f - vec3(1.0, 0.0, 0.0)), f.x),
                   mix(dot(c, f - vec3(0.0, 1.0, 0.0)), dot(d, f - vec3(1.0, 1.0, 0.0)), f.x), f.y),
               mix(mix(dot(e, f - vec3(0.0, 0.0, 1.0)), dot(g, f - vec3(1.0, 0.0, 1.0)), f.x),
                   mix(dot(h, f - vec3(0.0, 1.0, 1.0)), dot(j, f - vec3(1.0, 1.0, 1.0)), f.x), f.y), f.z);
}

float fbm(vec3 p) {
    float sum = 0.0;
    float amp = 1.0;
    float freq = 1.0;
    for (int i = 0; i < 5; ++i) {
        sum += noise(p * freq) * amp;
        amp *= 0.5;
        freq *= 2.0;
    }
    return sum;
}

vec3 getRay(vec2 uv, vec3 cameraPos, vec3 lookAt, float zoom) {
    vec3 forward = normalize(lookAt - cameraPos);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
    vec3 up = normalize(cross(forward, right));
    return normalize(forward * zoom + right * uv.x + up * uv.y);
}

float mapTerrain(vec3 p) {
    float h = fbm(p * 0.1 + vec3(0.0, iTime * 0.05, 0.0)) * 20.0;
    h += fbm(p * 0.4) * 5.0;
    h -= 10.0; // Base level for canyons
    return p.y - h; 
}

vec3 calculateNormal(vec3 p) {
    vec2 e = vec2(0.01, 0.0);
    return normalize(vec3(
        mapTerrain(p + e.xyy) - mapTerrain(p - e.xyy),
        mapTerrain(p + e.yxy) - mapTerrain(p - e.yxy),
        mapTerrain(p + e.yyx) - mapTerrain(p - e.yyx)
    ));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float camTime = iTime * 0.1;
    vec3 cameraPos = vec3(sin(camTime) * 100.0, 30.0 + sin(camTime * 0.5) * 10.0, cos(camTime) * 100.0);
    vec3 lookAt = vec3(0.0, -10.0, 0.0);
    vec3 rayDir = getRay(uv, cameraPos, lookAt, 2.0);

    float t = 0.0;
    float maxDist = 300.0;
    float hitDist = 0.01;

    for (int i = 0; i < 60; ++i) {
        vec3 p = cameraPos + rayDir * t;
        float dist = mapTerrain(p);
        if (dist < hitDist || t > maxDist) break;
        t += dist;
    }

    vec3 finalColor = vec3(0.0);

    if (t < maxDist) {
        vec3 p = cameraPos + rayDir * t;
        vec3 normal = calculateNormal(p);
        vec3 lightDir = normalize(vec3(0.5, 0.8, 0.6)); // Sun direction
        vec3 skyColor = vec3(0.5, 0.7, 0.9);
        vec3 groundColor = vec3(0.7, 0.5, 0.3);
        vec3 canyonColor = vec3(0.4, 0.3, 0.2);

        float diff = max(0.0, dot(normal, lightDir));

        vec3 materialColor = mix(groundColor, canyonColor, clamp((p.y + 20.0) / 20.0, 0.0, 1.0));
        finalColor = materialColor * diff * 0.8 + materialColor * 0.2;
        finalColor += skyColor * 0.2 * pow(max(0.0, dot(normal, vec3(0.0, 1.0, 0.0))), 2.0);

        // Atmospheric scattering
        float fogFactor = exp(-t * 0.005);
        finalColor = mix(skyColor, finalColor, fogFactor);

    } else {
        // Sky
        finalColor = vec3(0.5, 0.7, 0.9) - uv.y * 0.2 + 0.1 * pow(max(0.0, dot(rayDir, normalize(vec3(0.5, 0.8, 0.6)))), 4.0);
    }

    fragColor = vec4(finalColor, 1.0);
}

