               mix(mix(dot(e, f - vec3(0.0, 0.0, 1.0)), dot(g, f - vec3(1.0, 0.0, 1.0)), f.x),
                   mix(dot(h, f - vec3(0.0, 1.0, 1.0)), dot(j, f - vec3(1.0, 1.0, 1.0)), f.x), f.y), f.z);
}

float fbm(vec3 p) {
    float sum = 0.0;
    float amp = 1.0;
    float freq = 1.0;
    for (int i = 0; i < 5; ++i) {
