float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    fp = fp * fp * (3.0 - 2.0 * fp);
    return mix(mix(hash(ip), hash(ip + vec2(1.0, 0.0)), fp.x),
               mix(hash(ip + vec2(0.0, 1.0)), hash(ip + vec2(1.0, 1.0)), fp.x), fp.y);
}

float turbulence(vec2 p) {
    float w = 0.0;
    float freq = 1.0;
    for (int i = 0; i < 4; i++) {
        w += abs(noise(p * freq)) / freq;
        freq *= 2.0;
    }
    return w;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv.y = 1.0 - uv.y;

    float time = iTime * 0.1;

    // Sky color (gradient from light blue to slightly darker blue)
    vec3 skyColor = mix(vec3(0.6, 0.8, 1.0), vec3(0.3, 0.6, 0.9), uv.y);

    // Ocean
    float oceanLevel = 0.3 + sin(time * 0.5) * 0.05;
    vec3 oceanColor = mix(vec3(0.0, 0.1, 0.3), vec3(0.1, 0.4, 0.6), clamp(uv.y, 0.0, 1.0));

    // Waves
    float waveDistortion = turbulence(uv * 15.0 + vec2(time * 2.0, time * 1.5)) * 0.1;
    oceanColor += vec3(0.1, 0.1, 0.1) * smoothstep(0.0, 0.5, waveDistortion);

    // Hills
    float hillHeight = 0.3 + texture(BufferA, vec2(uv.x * 2.0 + time * 0.1, 0.0)).r * 0.4;
    hillHeight += noise(vec2(uv.x * 5.0, time * 0.5)) * 0.1; // Smaller details

    float hillLine = 0.35 - (uv.y * 0.8 - hillHeight + turbulence(vec2(uv.x * 2.0, time * 0.5)) * 0.1) * 2.0;
    hillLine = smoothstep(0.0, 0.05, hillLine);

    vec3 hillColor = mix(vec3(0.1, 0.4, 0.1), vec3(0.3, 0.6, 0.2), hillLine);
    hillColor = mix(hillColor, vec3(0.0, 0.2, 0.0), clamp((uv.y - (hillHeight * 0.7 + 0.3)) * 5.0, 0.0, 1.0)); // Shading toward bottom

    // Foreground closer hill
    float foregroundHillHeight = 0.5 + texture(BufferA, vec2(uv.x * 1.5 + time * 0.2, 0.0)).g * 0.3;
    foregroundHillHeight += noise(vec2(uv.x * 3.0, time * 0.3)) * 0.1;

    float foregroundHillLine = 0.5 - (uv.y * 0.8 - foregroundHillHeight) * 2.0;
    foregroundHillLine = smoothstep(0.0, 0.05, foregroundHillLine);

    vec3 foregroundHillColor = mix(vec3(0.2, 0.5, 0.2), vec3(0.4, 0.7, 0.3), foregroundHillLine);
    foregroundHillColor = mix(foregroundHillColor, vec3(0.0, 0.3, 0.0), clamp((uv.y - (foregroundHillHeight * 0.7 + 0.4)) * 5.0, 0.0, 1.0));

    vec3 finalColor = skyColor;

    // Draw hills over sky
    finalColor = mix(finalColor, hillColor, hillLine);

    // Draw foreground hill over distant hills
    finalColor = mix(finalColor, foregroundHillColor, foregroundHillLine);

    // Draw ocean over hills
    finalColor = mix(finalColor, oceanColor, smoothstep(0.0, 0.1, uv.y - oceanLevel));

    // Simple sun
    vec2 sunPos = vec2(0.8, 0.8);
    float sunDist = distance(uv, sunPos);
    float sunGlow = smoothstep(0.1, 0.0, sunDist);
    finalColor += vec3(1.0, 0.8, 0.5) * sunGlow * 0.5;
    finalColor = clamp(finalColor, 0.0, 1.0);

    // Apply a slight vignette
    float vignette = length(uv - 0.5) * 1.5;
    finalColor *= (1.0 - vignette * vignette * 0.5);

    fragColor = vec4(finalColor, 1.0);
}

