    float c = hash22(i + vec2(0.0, 1.0)).x;
    float d = hash22(i + vec2(1.0, 1.0)).x;
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fractalNoise(vec2 p) {
    float f = 0.0;
    float amplitude = 0.5;
    p *= 4.0;
    for (int i = 0; i < 4; ++i) {
        f += amplitude * noise(p);
        p *= 2.0;
        amplitude *= 0.5;
    }
    return f;
}

vec3 rotateX(vec3 p, float angle) {
